package com.zt.security.event;
import com.fasterxml.jackson.databind.*;
import com.zt.security.common.*;
import com.zt.security.runtime.AgentRuntimeEvent;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.context.request.*;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;

@Service @Transactional
public class SecurityActivityLedger {
 @org.springframework.beans.factory.annotation.Autowired private com.zt.security.workspace.WorkspaceAccess access;
 private final NamedParameterJdbcTemplate jdbc;private final TenantSession tenants;private final WorkspaceSession workspaces;private final ObjectMapper json;
 public SecurityActivityLedger(NamedParameterJdbcTemplate jdbc,TenantSession tenants,WorkspaceSession workspaces,ObjectMapper json){this.jdbc=jdbc;this.tenants=tenants;this.workspaces=workspaces;this.json=json;}
 public record Write(UUID id,boolean inserted){}
 public UUID selectedWorkspace(){var attrs=RequestContextHolder.getRequestAttributes();if(!(attrs instanceof ServletRequestAttributes request))return null;String value=request.getRequest().getHeader("X-Workspace-Id");return value==null?null:UUID.fromString(value);}
 private static String bounded(String value,int limit){if(value==null)return null;if(value.length()>limit||value.chars().anyMatch(Character::isISOControl))throw new IllegalArgumentException("Invalid common event field");return value;}
 public Map<String,Object> safeMetadata(Map<String,Object> source){
  Map<String,Object> result=new LinkedHashMap<>();if(source==null)return result;
  for(String key:List.of("auditEventId","callId","approvalId","contractId","executionId","sessionId","toolId","taskId","returnedCount","aclVersion","reason","errorCode","resultHash","latencyMs","riskAssessment","imported","actorType","operationType","observationState","threatScore","approvedBy","executedBy")){
   Object value=source.get(key);if(value instanceof UUID)value=value.toString();if(value instanceof String s)result.put(key,s.substring(0,Math.min(s.length(),key.equals("reason")?1024:512)));else if(value instanceof Number||value instanceof Boolean)result.put(key,value);
  }
  Object policies=source.get("matchedPolicies");if(policies!=null){var tree=json.valueToTree(policies);if(tree.isArray()){List<Map<String,Object>> refs=new ArrayList<>();for(var policy:tree){if(refs.size()>=200)break;Map<String,Object> ref=new LinkedHashMap<>();for(String key:List.of("id","name","effect","version")){var value=policy.get(key);if(value!=null&&value.isValueNode())ref.put(key,value.isNumber()?value.numberValue():value.asText().substring(0,Math.min(256,value.asText().length())));}refs.add(ref);}result.put("matchedPolicies",refs);}}
  return result;
 }
 public Write record(CommonSecurityEvent event){
  if(event.tenantId()==null||event.originId()==null||event.source()==null||!event.source().matches("[A-Z_]{1,32}")||event.stage()==null||!Set.of("AUTHORIZATION","EXECUTION","LIFECYCLE","OBSERVATION").contains(event.stage())||event.eventType()==null||!event.eventType().matches("[A-Za-z0-9_.:-]{1,120}")||event.action()==null||event.occurredAt()==null)throw new IllegalArgumentException("Invalid common security event");
  if(event.decision()!=null&&!Set.of("ALLOW","DENY","STEP_UP").contains(event.decision())||event.riskScore()!=null&&(!Double.isFinite(event.riskScore())||event.riskScore()<0||event.riskScore()>100))throw new IllegalArgumentException("Invalid event decision or risk score");
  var p=new MapSqlParameterSource().addValue("tenant",event.tenantId()).addValue("workspace",event.workspaceId());tenants.set(event.tenantId());workspaces.set(event.workspaceId());
  UUID id=UUID.randomUUID();String prefix="AUTHORIZATION_DECIDED".equals(event.eventType())?"audit":"FILE_ACCESS_DECIDED".equals(event.eventType())||Set.of("AUTH","FILE","SYNC").contains(event.source())?"file":"WORKFLOW".equals(event.source())&&event.eventType().startsWith("WORKFLOW_")?"workflow":event.source();String key=prefix.equals("audit")||prefix.equals("file")||prefix.equals("workflow")?prefix+":"+bounded(event.originId(),256):event.source()+":"+bounded(event.originId(),256)+":"+event.eventType();
  p.addValue("id",id).addValue("source",event.source()).addValue("type",event.eventType()).addValue("stage",event.stage()).addValue("origin",event.originId()).addValue("key",key).addValue("time",Timestamp.from(event.occurredAt())).addValue("correlation",bounded(event.correlationId(),512)).addValue("request",event.requestId()).addValue("caller",bounded(event.caller(),512)).addValue("human",bounded(event.humanSubject(),512)).addValue("ai",bounded(event.aiSubject(),512)).addValue("action",bounded(event.action(),255)).addValue("resourceType",bounded(event.resourceType(),128)).addValue("resource",bounded(event.resourceId(),512)).addValue("decision",event.decision()).addValue("status",bounded(event.status(),64)).addValue("risk",event.riskScore()).addValue("eligible",event.analysisEligible()&&event.aiSubject()!=null&&"AUTHORIZATION".equals(event.stage())&&event.decision()!=null);
  try{p.addValue("metadata",json.writeValueAsString(safeMetadata(event.metadata())));}catch(Exception e){throw new IllegalArgumentException("Invalid event metadata",e);}
  var inserted=jdbc.queryForList("INSERT INTO security_activities(id,tenant_id,workspace_id,source,event_type,stage,origin_id,event_key,occurred_at,correlation_id,request_id,caller_subject,human_subject,ai_subject,action,resource_type,resource_id,decision,status,risk_score,analysis_eligible,metadata) VALUES(:id,:tenant,:workspace,:source,:type,:stage,:origin,:key,:time,:correlation,:request,:caller,:human,:ai,:action,:resourceType,:resource,:decision,:status,:risk,:eligible,CAST(:metadata AS jsonb)) ON CONFLICT DO NOTHING RETURNING id",p);
  if(!inserted.isEmpty())return new Write(id,true);
  UUID existing=jdbc.queryForObject("SELECT id FROM security_activities WHERE tenant_id=:tenant AND workspace_id IS NOT DISTINCT FROM CAST(:workspace AS uuid) AND event_key=:key",p,UUID.class);return new Write(existing,false);
 }
 public String envelope(UUID id,CommonSecurityEvent event){Map<String,Object> result=new LinkedHashMap<>();result.put("schemaVersion",1);result.put("eventId",id);result.put("sourceEventId",event.originId());result.put("tenantId",event.tenantId());result.put("workspaceId",event.workspaceId());result.put("source",event.source());result.put("eventType",event.eventType());result.put("stage",event.stage());result.put("occurredAt",event.occurredAt().toString());result.put("correlationId",event.correlationId());result.put("requestId",event.requestId());result.put("caller",event.caller());result.put("humanSubject",event.humanSubject());result.put("aiSubject",event.aiSubject());result.put("action",event.action());result.put("resourceType",event.resourceType());result.put("resourceId",event.resourceId());result.put("decision",event.decision());result.put("status",event.status());result.put("riskScore",event.riskScore());result.put("metadata",safeMetadata(event.metadata()));try{return json.writeValueAsString(result);}catch(Exception e){throw new IllegalStateException(e);}}
 @Transactional(readOnly=true) public MapSqlParameterSource scope(UUID tenant,UUID workspace){tenants.set(tenant);workspaces.set(workspace);var auth=SecurityContextHolder.getContext().getAuthentication();if(auth==null||!auth.isAuthenticated())throw new org.springframework.security.access.AccessDeniedException("Authenticated event reader required");if(auth instanceof org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken&&workspace!=null)access.require(auth,tenant,workspace);boolean all=auth!=null&&auth.getAuthorities().stream().anyMatch(a->Set.of("ROLE_PLATFORM","ROLE_ADMIN","ROLE_AUDITOR","ROLE_POLICY_MANAGER","ROLE_SOC_ANALYST").contains(a.getAuthority()));return new MapSqlParameterSource().addValue("tenant",tenant).addValue("workspace",workspace).addValue("all",all).addValue("reader",auth==null?"":auth.getName());}
 public static final String VISIBLE="tenant_id=:tenant AND workspace_id IS NOT DISTINCT FROM CAST(:workspace AS uuid) AND (:all OR caller_subject=:reader OR human_subject=:reader OR ai_subject=:reader)";
 @Transactional(readOnly=true) public List<Map<String,Object>> recent(UUID tenant,UUID workspace,Instant since,int limit){var rows=jdbc.queryForList("SELECT id,origin_id AS \"sourceEventId\",source,event_type AS \"eventType\",stage,occurred_at AS \"occurredAt\",correlation_id AS \"correlationId\",request_id AS \"requestId\",caller_subject AS caller,human_subject AS \"humanSubject\",ai_subject AS \"aiSubject\",action,resource_type AS \"resourceType\",resource_id AS \"resourceId\",decision,status,risk_score AS \"riskScore\",analysis_eligible AS \"analysisEligible\",metadata FROM security_activities WHERE "+VISIBLE+" AND occurred_at>=:since ORDER BY occurred_at DESC,id DESC LIMIT :limit",scope(tenant,workspace).addValue("since",Timestamp.from(since)).addValue("limit",Math.min(1000,Math.max(1,limit))));for(var row:rows){Object metadata=row.get("metadata");try{row.put("metadata",json.readValue(String.valueOf(metadata),Map.class));}catch(Exception ex){throw new IllegalStateException("Invalid stored activity metadata",ex);}Object time=row.get("occurredAt");if(time instanceof Timestamp stamp)row.put("occurredAt",stamp.toInstant().toString());}return rows;}
 @Transactional(readOnly=true) public Map<String,Object> summary(UUID tenant,UUID workspace,Instant since){
  var p=scope(tenant,workspace).addValue("since",Timestamp.from(since));String visible=VISIBLE+" AND occurred_at>=:since";
  Map<String,Object> result=new LinkedHashMap<>(jdbc.queryForMap("SELECT count(*) AS \"eventCount\",count(*) FILTER(WHERE stage='LIFECYCLE') AS \"lifecycleCount\",count(*) FILTER(WHERE stage='EXECUTION') AS \"executionCount\",count(DISTINCT ai_subject) AS \"agentCount\",count(*) FILTER(WHERE metadata->>'imported'='true') AS \"importedCount\" FROM security_activities WHERE "+visible,p));
  var decisions=jdbc.queryForMap("SELECT count(*) AS \"decisionCount\",count(*) FILTER(WHERE decision='DENY') AS \"denyCount\",count(*) FILTER(WHERE decision='STEP_UP') AS \"stepUpCount\",count(*) FILTER(WHERE risk_score IS NULL) AS \"unmeasuredCount\",count(*) FILTER(WHERE risk_score IS NOT NULL) AS \"measuredCount\" FROM (SELECT DISTINCT ON(coalesce(request_id::text,id::text)) decision,risk_score FROM security_activities WHERE "+visible+" AND analysis_eligible ORDER BY coalesce(request_id::text,id::text),CASE WHEN source='RUNTIME' THEN 1 ELSE 0 END,occurred_at DESC) d",p);
  result.putAll(decisions);result.put("sources",jdbc.queryForList("SELECT source,count(*) AS count FROM security_activities WHERE "+visible+" GROUP BY source ORDER BY source",p));result.put("scope","WORKSPACE");result.put("workspaceId",workspace);result.put("schemaVersion",1);return result;
 }
 @Transactional(readOnly=true) public List<AgentRuntimeEvent> analysis(UUID tenant,UUID workspace){
  // One decisive sample per request, regardless of how many adapters recorded its stages.
  return jdbc.query("SELECT * FROM (SELECT DISTINCT ON (coalesce(request_id::text,id::text)) * FROM security_activities WHERE "+VISIBLE+" AND analysis_eligible ORDER BY coalesce(request_id::text,id::text),CASE WHEN source='RUNTIME' THEN 1 ELSE 0 END,occurred_at DESC) unique_decisions ORDER BY occurred_at DESC LIMIT 10000",scope(tenant,workspace),(rs,n)->{var event=new AgentRuntimeEvent();event.setId(rs.getObject("id",UUID.class));event.setTenantId(tenant);event.setWorkspaceId(workspace);event.setRequestId(rs.getObject("request_id",UUID.class));event.setAgentExternalId(rs.getString("ai_subject"));event.setAction(rs.getString("action"));event.setResourceType(rs.getString("resource_type"));event.setResourceId(rs.getString("resource_id"));event.setDecision(rs.getString("decision"));event.setRiskScore(rs.getObject("risk_score")==null?null:rs.getDouble("risk_score"));event.setCreatedAt(rs.getTimestamp("occurred_at").toInstant());return event;});
 }
}
